void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec2 g = vec2(0.02 + uv.x * 0.2, 0.0);
  vec3 a = textureGrad(iChannel0, uv * 4.0, g, g.yx).rgb;
  vec3 b = textureOffset(iChannel0, uv * 4.0, ivec2(1, 0)).rgb;
  fragColor = vec4(mix(a, b, step(0.5, uv.y)), 1.0);
}
